K = 'java'


def _ind(s, n):
    return '\n'.join((' ' * n + l) if l.strip() else '' for l in s.strip('\n').split('\n'))


def J(t, body, b=None, imp='', extra=''):
    code = (imp.strip() + '\n\n' if imp else '') + 'public class Main {\n' + (_ind(extra, 4) + '\n\n' if extra else '') + \
        '    public static void main(String[] args) throws Exception {\n' + _ind(body, 8) + '\n    }\n}\n'
    return dict(t=t, b=b, code=code, lang='java', run=True)


